const raw = ($input.first().json.candidates?.[0]?.content?.parts?.[0]?.text) || '';
const prev = $('Parse Validated Backend1').first().json;
let buggyCode = raw.replace(/^```[\w]*\s*\n?/gm, '').replace(/^```\s*$/gm, '').trim();
if (!buggyCode || buggyCode.length < 100) buggyCode = prev.backend_fixed;
// backend.code = buggy (student sees this), backend_solution.code = correct (for tests)
return [{ json: { ...prev, backend: { ...prev.backend, code: buggyCode } } }];

const raw = ($input.first().json.candidates?.[0]?.content?.parts?.[0]?.text) || '';
const prev = $('Parse Frontend Output1').first().json;
let buggyCode = raw.replace(/^\`\`\`[\w]*\s*\n?/gm, '').replace(/^\`\`\`\s*$/gm, '').trim();
if (!buggyCode || buggyCode.length < 100) buggyCode = prev.frontend_solution?.code || prev.frontend.code;
return [{ json: { ...prev, frontend: { ...prev.frontend, code: buggyCode } } }];

const body = $input.first().json.body ?? $input.first().json;
const group_id = body.group_id;
const group_code = body.group_code || '';
const description = body.description;
const frontend_language = body.frontend_language;
const backend_language = body.backend_language;
const db_style = body.db_style;
const token = body.token;
if (!group_id || !description) throw new Error('Missing required fields: group_id, description');
// Date.now() + Math.random() guarantees different bug_seed on every execution
const seedSource = `${group_id}|${Date.now()}|${Math.random()}`;
const bug_seed = Array.from(seedSource).reduce((acc, ch) => ((acc * 31 + ch.charCodeAt(0)) >>> 0), 7);
return [{ json: { group_id, group_code, description, frontend_language: frontend_language || 'react', backend_language: backend_language || 'python', db_style: db_style || 'csv', token: token || '', bug_seed } }];

function extract(raw, tag) {
  const open = '<<<' + tag + '>>>';
  const next = raw.indexOf('<<<', raw.indexOf(open) + open.length);
  const start = raw.indexOf(open) + open.length;
  const end = next === -1 ? raw.length : next;
  return raw.substring(start, end).trim();
}
const raw = ($input.first().json.candidates?.[0]?.content?.parts?.[0]?.text) || '';
if (!raw) throw new Error('Empty response from Gemini');
const fileName = extract(raw, 'FILENAME');
const schema_summary = extract(raw, 'SCHEMA_SUMMARY');
const code = extract(raw, 'CODE').replace('<<<END>>>', '').trim();
if (!fileName || !code) throw new Error('Could not extract fields:\n' + raw.substring(0, 400));
const prev = $('Parse Input1').first().json;
return [{ json: { ...prev, db: { fileName, code, schema_summary } } }];

