const raw = ($input.first().json.candidates?.[0]?.content?.parts?.[0]?.text) || '';
const prev = $('Parse Backend Output1').first().json;

let fixedCode = '';
try {
  fixedCode = extract(raw, 'FIXED_CODE').replace('<<<END>>>', '').trim();
} catch (e) {}

if (!fixedCode || fixedCode.length < 50) {
  fixedCode = prev.backend.code;
}

fixedCode = fixedCode.replace(/@app\.before_first_request\s*\n(\s*def \w+\(\):[\s\S]*?)(?=\n@|\ndef |\nclass |\napp\.run|\nif __name__)/g, (match, fnBody) => {
  const bodyLines = fnBody.split('\n').slice(1).map(l => l.replace(/^    /, ''));
  return '\n' + bodyLines.join('\n') + '\n';
});
fixedCode = fixedCode.replace(/^```[\w]*\s*\n?/gm, '').replace(/^```\s*$/gm, '').trim();
fixedCode = fixedCode.replace(/^#!\/.*\n?/m, '');
fixedCode = fixedCode.replace(/^[a-z]*\/bin\/env\s+\w+[\d.]*\s*\n?/m, '').trim();

const hasImport = /^(from |import )/m.test(fixedCode);
if (!hasImport) {
  fixedCode = 'from flask import Flask, request, jsonify, abort\nfrom flask_cors import CORS\nimport csv, os, json, uuid\n\n' + fixedCode;
}

return [{ json: { ...prev, backend_solution: { ...prev.backend, code: fixedCode }, backend_fixed: fixedCode } }];

