const raw = ($input.first().json.candidates?.[0]?.content?.parts?.[0]?.text) || '';
if (!raw) throw new Error('Empty response from Gemini');
const fileName = extract(raw, 'FILENAME');
let code = extract(raw, 'CODE').replace('<<<END>>>', '').trim();
if (!code) throw new Error('Could not extract frontend test code:
' + raw.substring(0, 400));

if (!code.includes("@testing-library/jest-dom")) {
  code = code.replace(/(import\s+React\s+from\s+['"]react['"];?\s*
)/, "$1import '@testing-library/jest-dom';
");
}

const appImportPattern = /^import\s+App\s+from\s+['"][^'"]*App(?:\.jsx|\.js)?['"];?\s*$/m;
if (appImportPattern.test(code)) {
  const resolver = "const loadApp = () => {
  const candidates = [
    './App',
    './App.jsx',
    './App.js',
    '../App',
    '../App.jsx',
    '../App.js',
    '../frontend/App',
    '../frontend/App.jsx',
    '../frontend/App.js',
    '../frontend/src/app/page',
    '../frontend/src/app/page.js',
    '../../frontend/src/app/page',
    '../../frontend/src/app/page.js',
    '../src/app/page',
    '../src/app/page.js'
  ];

  for (const candidate of candidates) {
    try {
      const mod = require(candidate);
      return mod && mod.default ? mod.default : mod;
    } catch (error) {}
  }

  throw new Error('Unable to resolve frontend component from known locations');
};
const App = loadApp();";
  code = code.replace(appImportPattern, resolver);
}

const prev = $('Parse Backend Tests1').first().json;
return [{ json: { ...prev, test_frontend: { fileName: fileName || 'App.test.jsx', code } } }];

function extract(raw, tag) {
  const open = '<<<' + tag + '>>>';
  const next = raw.indexOf('<<<', raw.indexOf(open) + open.length);
  const start = raw.indexOf(open) + open.length;
  const end = next === -1 ? raw.length : next;
  return raw.substring(start, end).trim();
}
const raw = ($input.first().json.candidates?.[0]?.content?.parts?.[0]?.text) || '';
if (!raw) throw new Error('Empty response from Gemini');
const fileName = extract(raw, 'FILENAME');
const code = extract(raw, 'CODE').replace('<<<END>>>', '').trim();
if (!code) throw new Error('Could not extract E2E test code:\n' + raw.substring(0, 400));
const prev = $('Parse Frontend Tests1').first().json;
return [{ json: { ...prev, test_e2e: { fileName: fileName || 'cypress/e2e/app.cy.js', code } } }];

// Full context is chained forward through each parse node — read everything from $input
const data = $input.first().json;

const group_id = data.group_id;
const group_code = data.group_code || '';
const token    = data.token || '';
const db       = data.db;
const backend  = data.backend;
const frontend = data.frontend;
const backend_solution = data.backend_solution;
const frontend_solution = data.frontend_solution;
const test_backend  = data.test_backend;
const test_frontend = data.test_frontend;
const test_e2e      = data.test_e2e;

if (!group_id)     throw new Error('Assemble: missing group_id');
if (!db)           throw new Error('Assemble: missing db');
if (!backend)      throw new Error('Assemble: missing backend');
if (!frontend)     throw new Error('Assemble: missing frontend');
if (!test_backend) throw new Error('Assemble: missing test_backend');
if (!test_frontend)throw new Error('Assemble: missing test_frontend');
if (!test_e2e)     throw new Error('Assemble: missing test_e2e');

const files = [
  { category: 'frontend', fileName: frontend.fileName, code: frontend.code, permission: 'read-write', visibility: 'visible' },
  { category: 'backend',  fileName: backend.fileName,  code: backend.code,  permission: 'read-write', visibility: 'visible' },
  { category: 'db',       fileName: db.fileName,       code: db.code,       permission: 'read',       visibility: 'visible' },
  { category: 'test', fileName: test_backend.fileName,  code: test_backend.code,  permission: 'read', visibility: 'hidden' },
  { category: 'test', fileName: test_frontend.fileName, code: test_frontend.code, permission: 'read', visibility: 'hidden' },
  { category: 'test', fileName: test_e2e.fileName,      code: test_e2e.code,      permission: 'read', visibility: 'hidden' }
];

if (backend_solution?.code) {
  files.push({ category: 'solution', fileName: `backend/solution_${backend.fileName.split('/').pop()}`, code: backend_solution.code, permission: 'read', visibility: 'hidden' });
}
if (frontend_solution?.code) {
  files.push({ category: 'solution', fileName: `frontend/solution_${frontend.fileName.split('/').pop()}`, code: frontend_solution.code, permission: 'read', visibility: 'hidden' });
}

return [{ json: { group_id, group_code, token, files } }];

const assembled = $('Assemble Output1').first().json;

// Use the unique group_code as the Supabase key (globally unique, safe across all instances).
// Falls back to group_${integer} only if group_code was not sent (backward compat).
const supabase_group_id = (assembled.group_code && assembled.group_code.trim())
  ? assembled.group_code.trim()
  : `group_${String(assembled.group_id)}`;

// Store SOLUTION (correct) files + db — NOT the buggy versions.
// The AI Tutor needs the correct codebase so it knows exactly what the bugs
// are and can guide students toward the right answer via Socratic questioning.
const codeFiles = assembled.files.filter(f => f.category === 'solution' || f.category === 'db');

const fullCodebase = codeFiles.map(f => {
  return `// ─── ${f.fileName} ───\n${f.code}`;
}).join('\n\n');

return [{ json: {
  group_id: supabase_group_id,
  codebase: fullCodebase,
  created_at: new Date().toISOString()
} }];

const backendResult = $('POST to Backend1').first().json;
const assembled = $('Assemble Output1').first().json;

return [{
  json: {
    success: true,
    message: 'All phases complete. Files posted + codebase stored.',
    group_id: assembled.group_id,
    files_generated: assembled.files.map(f => ({
      category: f.category,
      fileName: f.fileName,
      permission: f.permission,
      visibility: f.visibility
    })),
    backend_response: backendResult
  }
}];

// Pass ALL context through — only add debug fields as _debug sub-object
return [{ json: {
  ...$json,
  _debug: {
    has_backend: !!$json.backend,
    has_solution: !!$json.backend_solution,
    backend_len: $json.backend?.code?.length,
    solution_len: $json.backend_solution?.code?.length
  }
} }];
